<?php $filters=$filters??[];$pagination=$pagination??['current_page'=>1,'total_records'=>0,'total_pages'=>1];$canAccounts=in_array('accounts.view',$role_permissions??[],true);$canKyc=in_array('kyc.view',$role_permissions??[],true); ?>
<section class="admin-page-heading"><div><span class="admin-eyebrow">CLIENT OPERATIONS</span><h1>Users</h1><p>Search and review registered Client Portal accounts. Status actions preserve all user and Demo trading history.</p></div><span class="admin-count-pill"><?= (int)$pagination['total_records'] ?> users</span></section>
