        <label class="admin-search-field"><span>Search users</span><input type="search" name="search" value="<?= e($filters['search']??'') ?>" maxlength="100" placeholder="Name, email, user reference<?= $canAccounts?', account number':'' ?>" autocomplete="off" data-list-search></label>
        <label><span>User status</span><select name="status"><option value="all">All statuses</option><?php foreach(['active','suspended','disabled','pending','closed'] as $s): ?><option value="<?= e($s) ?>"<?= ($filters['status']??'all')===$s?' selected':'' ?>><?= e(ucwords($s)) ?></option><?php endforeach; ?></select></label>
        <?php if($canKyc): ?><label><span>Verification</span><select name="verification"><option value="all">All statuses</option><?php foreach(['not_submitted'=>'Not started','draft'=>'Draft','submitted'=>'Submitted','in_review'=>'Under review','verified'=>'Verified','resubmission_required'=>'Action required','rejected'=>'Rejected'] as $value=>$label): ?><option value="<?= e($value) ?>"<?= ($filters['verification']??'all')===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <?php if($canAccounts): ?><label><span>Demo Account</span><select name="account_status"><option value="all">Any account</option><option value="none"<?= ($filters['account_status']??'all')==='none'?' selected':'' ?>>No account</option><?php foreach(['active','suspended','disabled','closed'] as $s): ?><option value="<?= e($s) ?>"<?= ($filters['account_status']??'all')===$s?' selected':'' ?>><?= e(ucwords($s)) ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <label><span>Country</span><select name="country"><option value="">All countries</option><?php foreach($countries??[] as $country): ?><option value="<?= e($country) ?>"<?= ($filters['country']??'')===$country?' selected':'' ?>><?= e($country) ?></option><?php endforeach; ?></select></label>
        <label><span>Registration date</span><select name="date"><option value="all"<?= ($filters['date']??'all')==='all'?' selected':'' ?>>All time</option><option value="today"<?= ($filters['date']??'')==='today'?' selected':'' ?>>Today</option><option value="7d"<?= ($filters['date']??'')==='7d'?' selected':'' ?>>Last 7 days</option><option value="30d"<?= ($filters['date']??'')==='30d'?' selected':'' ?>>Last 30 days</option><option value="custom"<?= ($filters['date']??'')==='custom'?' selected':'' ?>>Custom range</option></select></label>
        <label class="admin-custom-date"><span>From</span><input type="date" name="from" value="<?= e(is_string($_GET['from']??null)?$_GET['from']:'') ?>"></label><label class="admin-custom-date"><span>To</span><input type="date" name="to" value="<?= e(is_string($_GET['to']??null)?$_GET['to']:'') ?>"></label>
        <label><span>Rows per page</span><select name="per_page"><?php foreach([25,50,100] as $n): ?><option value="<?= $n ?>"<?= (int)($filters['per_page']??25)===$n?' selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label>
        <input type="hidden" name="sort" value="<?= e($filters['sort']??'created') ?>"><input type="hidden" name="direction" value="<?= e(strtolower($filters['direction']??'DESC')) ?>"><input type="hidden" name="page" value="1">
        <button class="admin-button admin-button-primary" type="submit">Apply filters</button><a class="admin-button admin-button-secondary" href="<?= e(admin_url('users')) ?>">Reset</a>
    </form>
    <div class="admin-list-feedback" role="status" aria-live="polite" data-list-message></div>
    <div data-list-table><?php render('admin/users/table',['users'=>$users??[],'role_permissions'=>$role_permissions??[]]); ?></div>
